import xml.etree.ElementTree as ET
from bs4 import BeautifulSoup
from source_gate import corrected_controls

def run():
    xml = ET.parse(ROOT / 'raw/sources/technician_repeat.xml')
    tables = {t.attrib['id']: ' '.join(t.itertext()) for t in xml.findall('.//table-wrap')}
    soup = BeautifulSoup((ROOT / 'raw/sources/crowngen.html').read_text(), 'html.parser')
    cg = soup.get_text(' ', strip=True)
